import math, random

def bellman_ford_row(n, edges, s):
    d = [math.inf] * n
    d[s] = 0
    for _ in range(n - 1):
        for u, v, w in edges:
            if d[u] + w < d[v]:
                d[v] = d[u] + w
    return d

assert all_pairs(1, []) == [[0]]
D = all_pairs(3, [(0, 1, 4), (1, 2, -2), (0, 2, 5), (0, 1, 3)])
assert D == [[0, 3, 1], [math.inf, 0, -2], [math.inf, math.inf, 0]]
try:
    all_pairs(3, [(0, 1, 1), (1, 2, -3), (2, 0, 1)])
    raise AssertionError("a negative cycle must raise ValueError")
except ValueError:
    pass
rng = random.Random(6)
for _ in range(40):
    n = rng.randint(2, 8)
    potential = [rng.randint(-10, 10) for _ in range(n)]
    edges = []
    for _ in range(rng.randint(0, 20)):
        u, v = rng.randrange(n), rng.randrange(n)
        if u != v:
            # w = base + p(v) - p(u): edges may be negative, but every cycle has weight >= 0
            edges.append((u, v, rng.randint(0, 9) + potential[v] - potential[u]))
    D = all_pairs(n, edges)
    for s in range(n):
        assert D[s] == bellman_ford_row(n, edges, s), (n, edges, s)

