import random
from math import comb

grid = {}
for r in range(5):
    for c in range(5):
        nbrs = []
        if r < 4: nbrs.append(((r + 1, c), 1))
        if c < 4: nbrs.append(((r, c + 1), 1))
        grid[(r, c)] = nbrs
counts = count_shortest_paths(grid, (0, 0))
assert counts[(4, 4)] == comb(8, 4) == 70
assert counts[(2, 3)] == comb(5, 2)
diamond = {"s": [("a", 2), ("b", 1)], "a": [("t", 1)], "b": [("t", 2), ("a", 1)]}
assert count_shortest_paths(diamond, "s") == {"s": 1, "b": 1, "a": 2, "t": 3}
assert count_shortest_paths({"x": []}, "x") == {"x": 1}

def brute(graph, s):
    best, ways = {}, {}
    def walk(u, d, seen):
        if u not in best or d < best[u]:
            best[u], ways[u] = d, 1
        elif d == best[u]:
            ways[u] += 1
        for v, w in graph.get(u, []):
            if v not in seen:
                walk(v, d + w, seen | {v})
    walk(s, 0, {s})
    return ways

rng = random.Random(12)
for _ in range(60):
    n = rng.randint(2, 7)
    g = {v: [] for v in range(n)}
    for _ in range(rng.randint(1, 14)):
        u, v = rng.randrange(n), rng.randrange(n)
        if u != v:
            g[u].append((v, rng.randint(1, 3)))
    assert count_shortest_paths(g, 0) == brute(g, 0), g

